function validate([n, corridors]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is a whole number from 2 to 1000.';
  if (!Array.isArray(corridors) || corridors.length < 1 || corridors.length > 50000) return 'corridors needs 1 to 50000 entries.';
  const seen = new Set();
  for (const corridor of corridors) {
    if (!Array.isArray(corridor) || corridor.length !== 2) return 'Each corridor is a pair [room1, room2].';
    const [a, b] = corridor;
    if (![a, b].every(r => Number.isInteger(r) && r >= 1 && r <= n)) return 'Rooms are numbered from 1 to n.';
    if (a === b) return 'A corridor joins two different rooms.';
    const key = Math.min(a, b) * 1001 + Math.max(a, b);
    if (seen.has(key)) return 'Each pair of rooms has at most one corridor.';
    seen.add(key);
  }
  return null;
}

