function numberOfPaths(n, corridors) {
  const higher = Array.from({ length: n + 1 }, () => new Set());
  for (const [a, b] of corridors) {
    higher[Math.min(a, b)].add(Math.max(a, b));
  }
  let cycles = 0;
  for (let room = 1; room <= n; room++) {
    for (const second of higher[room]) {
      for (const third of higher[second]) {
        if (higher[room].has(third)) {
          cycles++;
        }
      }
    }
  }
  return cycles;
}

