function numberOfPaths(n, corridors) {
  const linked = new Set(corridors.map(([a, b]) => a + ',' + b).concat(corridors.map(([a, b]) => b + ',' + a)));
  const rooms = [...new Set(corridors.flat())].sort((x, y) => x - y);
  let count = 0;
  for (let i = 0; i < rooms.length; i++)
    for (let j = i + 1; j < rooms.length; j++)
      for (let k = j + 1; k < rooms.length; k++) {
        const [x, y, z] = [rooms[i], rooms[j], rooms[k]];
        if (linked.has(x + ',' + y) && linked.has(y + ',' + z) && linked.has(x + ',' + z)) count++;
      }
  return count;
}

