function generate(rand, size) {
  let n, m;
  if (size === 'large') {
    const dense = rand() < 0.5;
    n = dense ? 60 + Math.floor(rand() * 60) : 1000;
    m = Math.min(2000, n * (n - 1) / 2);
  } else {
    n = 2 + Math.floor(rand() * 7);
    const most = n * (n - 1) / 2;
    m = 1 + Math.floor(rand() * most);
  }
  const seen = new Set();
  const corridors = [];
  while (corridors.length < m) {
    const a = 1 + Math.floor(rand() * n);
    const b = 1 + Math.floor(rand() * n);
    if (a === b) continue;
    const key = Math.min(a, b) * 2000 + Math.max(a, b);
    if (seen.has(key)) continue;
    seen.add(key);
    corridors.push([a, b]);
  }
  return [n, corridors];
}
